import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import SsoOptions from './SsoOptions';

const LoginForm = () => {
    const navigate = useNavigate();

    const [formData, setFormData] = useState({
        email: '',
        password: ''
    });

    const [errors, setErrors] = useState({});
    const [showPassword, setShowPassword] = useState(false);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));

        // Clear error when user types
        if (errors[name]) {
            setErrors(prev => ({
                ...prev,
                [name]: undefined
            }));
        }
    };

    const handleKeyDown = (e) => {
        if (e.key === " ") {
            e.preventDefault();
        }
    };

    const handleSubmit = (e) => {
        e.preventDefault();

        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        const { email, password } = formData;
        const newErrors = {};
        let isValid = true;

        if (!emailRegex.test(email) || email == "") {
            newErrors.email = "Please enter a valid email address";
            isValid = false;
        }

        if (password.length < 6 || password == "") {
            newErrors.password = "Password must be at least 6 characters long";
            isValid = false;
        }

        setErrors(newErrors);

        if (!isValid) {
            return;
        }

        alert("Login successful");

        // Reset form
        setFormData({
            email: '',
            password: ''
        });
        setErrors({});

        navigate('/dashboard');
    };

    return (
        <form className="space-y-4" onSubmit={handleSubmit}>
            {/* Email Field */}
            <div className="space-y-2">
                <label className="font-label-md text-label-md text-on-surface" htmlFor="email">Email</label>
                <div className="relative">
                    <input 
                        className={`w-full h-12 px-4 bg-white rounded-lg border ${errors.email ? 'border-error focus:border-error focus:ring-error/20' : 'border-outline-variant focus:border-secondary focus:ring-secondary/20'} focus:outline-none focus:ring-2 transition-all font-body-md text-body-md text-on-surface placeholder:text-outline`} 
                        id="email" 
                        name="email" 
                        placeholder="name@company.com"  
                        type="email" 
                        onChange={handleChange} 
                        value={formData.email} 
                    />
                </div>
                {errors.email && <p className="text-error text-sm mt-1">{errors.email}</p>}
            </div>

            {/* Password Field */}
            <div className="space-y-">
                <div className="flex justify-between items-center">
                    <label className="font-label-md text-label-md text-on-surface" htmlFor="password">Password</label>
                    <Link className="font-label-sm text-label-sm text-secondary hover:underline transition-all" to="/forget-password">Forgot Password?</Link>
                </div>
                <div className="relative">
                    <input 
                        className={`w-full h-12 pl-4 pr-10 bg-white rounded-lg border ${errors.password ? 'border-error focus:border-error focus:ring-error/20' : 'border-outline-variant focus:border-secondary focus:ring-secondary/20'} focus:outline-none focus:ring-2 transition-all font-body-md text-body-md text-on-surface`} 
                        id="password" 
                        name="password"
                        placeholder="••••••••" 
                        type={showPassword ? "text" : "password"} 
                        onChange={handleChange} 
                        value={formData.password}
                        onKeyDown={handleKeyDown}
                    />
                    <span 
                        className="material-symbols-outlined absolute right-3 top-1/2 -translate-y-1/2 text-on-surface-variant cursor-pointer hover:text-on-surface" 
                        onClick={() => setShowPassword(!showPassword)}
                    >
                        {showPassword ? 'visibility' : 'visibility_off'}
                    </span>
                </div>
                {errors.password && <p className="text-error text-sm mt-1">{errors.password}</p>}
            </div>

            {/* CTA Button */}
            <button className="w-full h-12 bg-secondary text-white font-label-md text-label-md rounded-lg hover:bg-primary-container active:scale-[0.98] transition-all shadow-sm flex items-center justify-center gap-2" type="submit">
                <span>Log In</span>
                <span className="material-symbols-outlined" style={{ fontSize: '18px' }}>login</span>
            </button>

            <SsoOptions />
        </form>
    );
};

export default LoginForm;
